import React, { useState } from 'react';
import {
  BarChart3,
  TrendingUp,
  Zap,
  Gauge,
  Award,
  Layers,
  Sparkles,
  Activity,
  Cpu,
  Brain,
  ShieldCheck,
  CheckCircle2,
  RefreshCw,
  Search,
  Filter,
  Calendar,
  Clock,
  PieChart,
  ArrowUpRight,
  Flame,
  Droplets,
  Wind,
} from 'lucide-react';
import ProductionChart from '../components/ProductionChart';
import EnergyCard from '../components/EnergyCard';
import HealthTrendChart from '../components/HealthTrendChart';

const AnalyticsPage = () => {
  const [selectedShift, setSelectedShift] = useState('FullDay'); // ShiftA | ShiftB | ShiftC | FullDay
  const [selectedPlantFilter, setSelectedPlantFilter] = useState('All');
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [optSuccess, setOptSuccess] = useState(null);

  // 30 Machine Health Heatmap Matrix
  const loomHeatmap = [
    { id: 'LOOM-101', plant: 'Coimbatore', score: 98, status: 'Optimal', type: 'Air Jet', oee: 97.2 },
    { id: 'LOOM-102', plant: 'Coimbatore', score: 94, status: 'Optimal', type: 'Rapier', oee: 95.8 },
    { id: 'LOOM-103', plant: 'Coimbatore', score: 99, status: 'Optimal', type: 'Air Jet', oee: 98.6 },
    { id: 'LOOM-104', plant: 'Coimbatore', score: 88, status: 'Idle', type: 'Water Jet', oee: 84.1 },
    { id: 'LOOM-105', plant: 'Coimbatore', score: 96, status: 'Optimal', type: 'Rapier', oee: 96.0 },

    { id: 'LOOM-201', plant: 'Tirupur', score: 68, status: 'Critical Risk', type: 'Rapier', oee: 62.4 },
    { id: 'LOOM-202', plant: 'Tirupur', score: 95, status: 'Optimal', type: 'Rapier', oee: 94.5 },
    { id: 'LOOM-203', plant: 'Tirupur', score: 97, status: 'Optimal', type: 'Air Jet', oee: 96.8 },

    { id: 'LOOM-301', plant: 'Gujarat', score: 96, status: 'Optimal', type: 'Air Jet', oee: 95.9 },
    { id: 'LOOM-302', plant: 'Gujarat', score: 91, status: 'Idle', type: 'Air Jet', oee: 89.2 },
    { id: 'LOOM-303', plant: 'Gujarat', score: 99, status: 'Optimal', type: 'Water Jet', oee: 98.8 },

    { id: 'LOOM-401', plant: 'Kanchipuram', score: 97, status: 'Optimal', type: 'Rapier', oee: 96.5 },
    { id: 'LOOM-402', plant: 'Kanchipuram', score: 98, status: 'Optimal', type: 'Rapier', oee: 97.4 },

    { id: 'LOOM-501', plant: 'Salem', score: 72, status: 'Warning', type: 'Air Jet', oee: 78.5 },
    { id: 'LOOM-502', plant: 'Salem', score: 96, status: 'Optimal', type: 'Air Jet', oee: 95.2 },

    { id: 'LOOM-601', plant: 'Surat', score: 99, status: 'Optimal', type: 'Water Jet', oee: 98.9 },
    { id: 'LOOM-602', plant: 'Surat', score: 90, status: 'Idle', type: 'Rapier', oee: 88.0 },
    { id: 'LOOM-603', plant: 'Surat', score: 98, status: 'Optimal', type: 'Rapier', oee: 97.1 },
    { id: 'LOOM-604', plant: 'Surat', score: 95, status: 'Optimal', type: 'Air Jet', oee: 94.8 },
    { id: 'LOOM-605', plant: 'Surat', score: 99, status: 'Optimal', type: 'Rapier', oee: 98.7 },

    { id: 'LOOM-701', plant: 'Coimbatore', score: 97, status: 'Optimal', type: 'Sizing', oee: 96.4 },
    { id: 'LOOM-702', plant: 'Tirupur', score: 96, status: 'Optimal', type: 'Knitting', oee: 95.5 },
    { id: 'LOOM-703', plant: 'Gujarat', score: 79, status: 'Caution', type: 'Projectile', oee: 81.2 },
    { id: 'LOOM-704', plant: 'Kanchipuram', score: 98, status: 'Optimal', type: 'Velvet', oee: 97.9 },
    { id: 'LOOM-705', plant: 'Salem', score: 99, status: 'Optimal', type: 'Air Jet', oee: 98.5 },
    { id: 'LOOM-801', plant: 'Salem', score: 97, status: 'Optimal', type: 'Air Jet', oee: 96.1 },
    { id: 'LOOM-802', plant: 'Tirupur', score: 98, status: 'Optimal', type: 'Rapier', oee: 97.6 },
    { id: 'LOOM-803', plant: 'Coimbatore', score: 99, status: 'Optimal', type: 'Air Jet', oee: 98.8 },
    { id: 'LOOM-804', plant: 'Kanchipuram', score: 97, status: 'Optimal', type: 'Rapier', oee: 96.2 },
    { id: 'LOOM-805', plant: 'Surat', score: 99, status: 'Optimal', type: 'Rapier', oee: 98.9 },
  ];

  const handleRunAiOptimization = () => {
    setIsOptimizing(true);
    setTimeout(() => {
      setIsOptimizing(false);
      setOptSuccess('AI Plant Optimization complete! Re-balanced loom load factors across 30 assets, reducing energy rate by 4.2%!');
      setTimeout(() => setOptSuccess(null), 5000);
    }, 1200);
  };

  const filteredHeatmap = loomHeatmap.filter(
    (l) => selectedPlantFilter === 'All' || l.plant.toLowerCase() === selectedPlantFilter.toLowerCase()
  );

  return (
    <div style={{ padding: '1.5rem', background: '#F8FAFC', borderRadius: '16px', minHeight: 'calc(100vh - 120px)' }}>

      {/* 1. PAGE HEADER */}
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
            <h1 style={{ color: '#0F172A', fontSize: '1.5rem', fontWeight: '900' }}>📊 Plant Performance, OEE & AI Analytics Center</h1>
            <span className="badge badge-running" style={{ fontWeight: '800' }}>
              Overall Plant OEE: 96.4%
            </span>
          </div>
          <p style={{ color: '#475569', fontSize: '0.85rem', fontWeight: '600', marginTop: '4px' }}>
            Real-Time Analytics for Equipment Efficiency (OEE), Specific Energy Consumption, Defect Analytics, and Machine Health Heatmaps
          </p>
        </div>

        <button className="btn btn-primary" onClick={handleRunAiOptimization} disabled={isOptimizing} style={{ background: '#2563EB', fontWeight: '800' }}>
          <Sparkles size={16} className={isOptimizing ? 'spin' : ''} /> {isOptimizing ? 'Optimizing...' : 'Run AI OEE Optimizer'}
        </button>
      </div>

      {optSuccess && (
        <div style={{ padding: '0.9rem 1.25rem', background: '#DCFCE7', border: '1px solid #16A34A', borderRadius: '10px', color: '#166534', fontWeight: '800', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <CheckCircle2 size={18} /> {optSuccess}
        </div>
      )}

      {/* 2. OEE FORMULA DECOMPOSITION CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(230px, 1fr))', gap: '1.25rem', marginBottom: '1.75rem' }}>

        {/* Overall OEE */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '2px solid #2563EB' }}>
          <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '800' }}>OVERALL EQUIPMENT EFFICIENCY (OEE)</div>
          <div style={{ fontSize: '2rem', fontWeight: '900', color: '#2563EB', marginTop: '4px' }}>96.4%</div>
          <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '4px', fontWeight: '800' }}>+1.8% vs World Class Benchmark (85%)</div>
        </div>

        {/* Availability */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '800' }}>AVAILABILITY INDEX (Uptime)</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: '#0F172A', marginTop: '4px' }}>98.2%</div>
          <div style={{ fontSize: '0.72rem', color: '#64748B', marginTop: '4px', fontWeight: '700' }}>Unplanned Stoppages &lt; 1.8%</div>
        </div>

        {/* Performance */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '800' }}>PERFORMANCE INDEX (Speed Rate)</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: '#0F172A', marginTop: '4px' }}>97.5%</div>
          <div style={{ fontSize: '0.72rem', color: '#64748B', marginTop: '4px', fontWeight: '700' }}>Avg Speed: 1,080 RPM Baseline</div>
        </div>

        {/* Quality */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '800' }}>QUALITY INDEX (Yield)</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: '#16A34A', marginTop: '4px' }}>99.1%</div>
          <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '4px', fontWeight: '800' }}>First-Choice Grade A Fabric</div>
        </div>

      </div>

      {/* 3. 30-LOOM MACHINE HEALTH & OEE HEATMAP MATRIX */}
      <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem', background: '#ffffff', borderRadius: '14px', border: '1px solid #E2E8F0' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem', flexWrap: 'wrap', gap: '1rem' }}>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '900', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Cpu size={20} style={{ color: '#2563EB' }} /> 30-Machine Plant Health & OEE Heatmap Matrix
            </h3>
            <p style={{ fontSize: '0.78rem', color: '#64748B', fontWeight: '600', marginTop: '2px' }}>
              Real-time health score & OEE efficiency status across all 30 weaving looms
            </p>
          </div>

          {/* Plant Location Filter */}
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {['All', 'Coimbatore', 'Tirupur', 'Gujarat', 'Kanchipuram', 'Salem', 'Surat'].map((p) => (
              <button
                key={p}
                onClick={() => setSelectedPlantFilter(p)}
                style={{
                  padding: '0.4rem 0.75rem',
                  fontSize: '0.78rem',
                  fontWeight: '800',
                  borderRadius: '6px',
                  border: `1.5px solid ${selectedPlantFilter === p ? '#2563EB' : '#CBD5E1'}`,
                  background: selectedPlantFilter === p ? '#EFF6FF' : '#ffffff',
                  color: selectedPlantFilter === p ? '#2563EB' : '#475569',
                  cursor: 'pointer',
                }}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        {/* Heatmap Grid */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(135px, 1fr))', gap: '0.85rem' }}>
          {filteredHeatmap.map((m) => {
            const isGood = m.score >= 90;
            const isWarning = m.score >= 75 && m.score < 90;
            const isCritical = m.score < 75;

            const bg = isCritical ? '#FEE2E2' : isWarning ? '#FEF3C7' : '#DCFCE7';
            const border = isCritical ? '#EF4444' : isWarning ? '#F59E0B' : '#16A34A';
            const text = isCritical ? '#991B1B' : isWarning ? '#92400E' : '#166534';

            return (
              <div
                key={m.id}
                style={{
                  padding: '0.85rem',
                  borderRadius: '10px',
                  background: bg,
                  border: `1.5px solid ${border}`,
                  textAlign: 'center',
                  transition: 'all 0.2s ease',
                  cursor: 'pointer',
                }}
                title={`${m.id} (${m.plant}) - Health: ${m.score}% | OEE: ${m.oee}%`}
              >
                <div style={{ fontSize: '0.74rem', fontWeight: '900', color: text, fontFamily: 'JetBrains Mono' }}>
                  {m.id}
                </div>
                <div style={{ fontSize: '1.25rem', fontWeight: '900', color: text, margin: '2px 0' }}>
                  {m.score}%
                </div>
                <div style={{ fontSize: '0.68rem', fontWeight: '800', color: text }}>
                  OEE: {m.oee}%
                </div>
                <div style={{ fontSize: '0.64rem', color: '#64748B', fontWeight: '700', marginTop: '2px' }}>
                  {m.plant}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 4. PRODUCTION & HEALTH CHARTS ROW */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '1.5rem', marginBottom: '1.75rem' }}>
        <ProductionChart />
        <HealthTrendChart />
      </div>

      {/* 5. ENERGY BREAKDOWN PANEL */}
      <div style={{ marginBottom: '1.75rem' }}>
        <EnergyCard />
      </div>
    </div>
  );
};

export default AnalyticsPage;
